SELECT SUM(TOTAL_BYTES) AS "STORAGE_TOP_TABLES_BYTES" FROM (SELECT "ID" AS TABLE_ID, "TABLE_NAME" AS TABLE_NAME, "TABLE_CATALOG" AS DATABASE_NAME, "TABLE_SCHEMA" AS SCHEMA_NAME, "CLONE_GROUP_ID" AS CLONE_GROUP_ID, "ACTIVE_BYTES" AS ACTIVE_BYTES, "TIME_TRAVEL_BYTES" AS TIME_TRAVEL_BYTES, "FAILSAFE_BYTES" AS FAILSAFE_BYTES, "RETAINED_FOR_CLONE_BYTES" AS RETAINED_FOR_CLONE_BYTES, "ACTIVE_BYTES" + "TIME_TRAVEL_BYTES" + "FAILSAFE_BYTES" + "RETAINED_FOR_CLONE_BYTES" AS TOTAL_BYTES, "RETENTION_TIME" AS RETENTION_DAYS, "IS_TRANSIENT" AS IS_TRANSIENT, COALESCE("DELETED", FALSE) AS IS_DELETED, (TRY_TO_TIMESTAMP_NTZ("TABLE_CREATED")) AS TABLE_CREATED_AT, (TRY_TO_TIMESTAMP_NTZ("TABLE_DROPPED")) AS TABLE_DROPPED_AT, (TRY_TO_TIMESTAMP_NTZ("TABLE_ENTERED_FAILSAFE")) AS ENTERED_FAILSAFE_AT, (TRY_TO_TIMESTAMP_NTZ("_LOADED_AT")) AS SNAPSHOT_AT, (CAST(CASE WHEN (86400) = 0 OR (86400) IS NULL THEN NULL ELSE CAST(((DATEDIFF(SECOND, (TRY_TO_TIMESTAMP_NTZ("TABLE_CREATED")), (TRY_TO_TIMESTAMP_NTZ("_LOADED_AT"))))) AS DECIMAL(38, 15)) / CAST((86400) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15))) AS DAYS_SINCE_LAST_CHANGE, (NULL) AS ACCOUNT_NAME /* The account this snapshot came from (see the ACCOUNT_OF shim). */ FROM table_storage_metrics) AS base ORDER BY "STORAGE_TOP_TABLES_BYTES" DESC NULLS LAST LIMIT 100
